import { NextRequest, NextResponse } from 'next/server'
import { Storage, File } from '@google-cloud/storage'

// Initialize Google Cloud Storage client using Application Default Credentials
const storage = new Storage({
  projectId: process.env.GOOGLE_CLOUD_PROJECT_ID || 'landbrugsdata',
  // Use Application Default Credentials (ADC) - works if gcloud is authenticated
})

const BUCKET_NAME = 'landbrugsdata-raw-data'
const PMTILES_BASE_PATH = 'gold/pmtiles'

// Cache for 1 hour in development, 24 hours in production
const CACHE_DURATION = process.env.NODE_ENV === 'production' ? 86400 : 3600

interface TimestampFile {
  timestamp: string
  file: File
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> }
) {
  try {
    const resolvedParams = await params
    const path = resolvedParams.path.join('/')
    
    // Extract year and resolution from path
    // Expected format: h3_pfas_2023_res10.pmtiles
    const pmtilesMatch = path.match(/h3_pfas_(\d{4})_res(\d+)\.pmtiles/)
    if (!pmtilesMatch) {
      return NextResponse.json(
        { error: 'Invalid PMTiles path format' },
        { status: 400 }
      )
    }
    
    const [, year, resolution] = pmtilesMatch
    
    // Find the latest timestamp for this year/resolution combination
    const prefix = `${PMTILES_BASE_PATH}/h3_pfas_${year}_res${resolution}/`
    const [files] = await storage.bucket(BUCKET_NAME).getFiles({
      prefix,
      delimiter: '/',
    })
    
    // Find the latest timestamp directory
    const timestampDirs = files
      .filter(file => file.name.includes('/') && file.name.endsWith('.pmtiles'))
      .map(file => {
        const match = file.name.match(/\/(\d{8}_\d{6})\//)
        return match ? { timestamp: match[1], file } : null
      })
      .filter((item): item is TimestampFile => item !== null)
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp))
    
    if (timestampDirs.length === 0) {
      return NextResponse.json(
        { error: `PMTiles not found for year ${year} resolution ${resolution}` },
        { status: 404 }
      )
    }
    
    const latestFile = timestampDirs[0]!.file
    
    // Handle range requests for PMTiles
    const range = request.headers.get('range')
    
    if (range) {
      // Parse range header
      const rangeMatch = range.match(/bytes=(\d+)-(\d*)/)
      if (!rangeMatch) {
        return NextResponse.json(
          { error: 'Invalid range header' },
          { status: 416 }
        )
      }
      
      const start = parseInt(rangeMatch[1])
      const end = rangeMatch[2] ? parseInt(rangeMatch[2]) : undefined
      
      // Download the range from GCS
      const [buffer] = await latestFile.download({
        start,
        end: end !== undefined ? end + 1 : undefined,
      })
      
      // Get file metadata for Content-Range header
      const [metadata] = await latestFile.getMetadata()
      const fileSize = parseInt(metadata.size?.toString() || '0')
      const actualEnd = end !== undefined ? Math.min(end, fileSize - 1) : fileSize - 1
      
      return new NextResponse(buffer, {
        status: 206,
        headers: {
          'Content-Type': 'application/octet-stream',
          'Content-Length': buffer.length.toString(),
          'Content-Range': `bytes ${start}-${actualEnd}/${fileSize}`,
          'Accept-Ranges': 'bytes',
          'Cache-Control': `public, max-age=${CACHE_DURATION}`,
          'ETag': metadata.etag || `"${metadata.generation}"`,
        },
      })
    } else {
      // Full file download
      const [buffer] = await latestFile.download()
      const [metadata] = await latestFile.getMetadata()
      
      return new NextResponse(buffer, {
        status: 200,
        headers: {
          'Content-Type': 'application/octet-stream',
          'Content-Length': buffer.length.toString(),
          'Accept-Ranges': 'bytes',
          'Cache-Control': `public, max-age=${CACHE_DURATION}`,
          'ETag': metadata.etag || `"${metadata.generation}"`,
          'Last-Modified': metadata.updated || new Date().toUTCString(),
        },
      })
    }
  } catch (error) {
    console.error('PMTiles proxy error:', error)
    
    return NextResponse.json(
      { 
        error: 'Failed to fetch PMTiles',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    )
  }
} 